  newId?: Maybe<Scalars['String']['output']>;
  /**  The file number within organization context  */
  number?: Maybe<Scalars['Int']['output']>;
  /**  Numeric id to define the money transaction  */
  paymentOrder?: Maybe<Scalars['String']['output']>;
  /**  Date marking the end of the period for which payment transactions are included  */
  paymentPeriodEndDay?: Maybe<Scalars['String']['output']>;
  /**  Date marking the beginning of the period for which payment transactions are included  */
