  /**  Whether this is a trial subscription. Trial subscriptions provide temporary free access to the plan features for a limited period (defined by SubscriptionPlan.trialDays)  */
  isTrial?: Maybe<Scalars['Boolean']['output']>;
  newId?: Maybe<Scalars['String']['output']>;
  /**  Organization that has this subscription  */
  organization?: Maybe<Organization>;
  /**  Client-side device identification used for the anti-fraud detection. Example `{ "dv":1, "fingerprint":"VaxSw2aXZa"}`. Where the `fingerprint` should be the same for the same devices and it's not linked to the user ID. It's the device ID like browser / mobile application / remote system  */
  sender?: Maybe<SenderField>;
  /**  Subscription start date  */
  startAt?: Maybe<Scalars['String']['output']>;
  /**  Subscription context status. CREATED - context created but not yet active, DONE - context is fully processed and active, ERROR - processing failed  */
  status?: Maybe<SubscriptionContextStatusType>;
  /**  Subscription plan selected by the organization  */
